import { readFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));

const WORLDS_DIR = resolve(here, "../data/worlds");

/**
 * Static knowledge about one map. Loaded once from data/worlds/<id>.json
 * (generated by scripts/build-world.mjs from the client's Tiled maps).
 * `loadWorld()` with no argument gives the office, the map everyone starts in.
 */
export function loadWorld(pathOrId) {
  const path = !pathOrId
    ? resolve(WORLDS_DIR, "office.json")
    : /[\\/]|\.json$/.test(pathOrId)
      ? pathOrId
      : resolve(WORLDS_DIR, `${pathOrId}.json`);
  const raw = JSON.parse(readFileSync(path, "utf8"));
  const { tile, cols, rows, solid } = raw;

  const isSolidCell = (cx, cy) =>
    cx < 0 || cy < 0 || cx >= cols || cy >= rows || solid[cy][cx] === "1";

  /**
   * The player sprite is 32x48 and its physics body sits at the feet, so the
   * point we test is a little below the sprite centre (see client Player).
   */
  const FOOT_OFFSET_Y = 20;
  const isSolidAt = (x, y) =>
    isSolidCell(Math.floor(x / tile), Math.floor((y + FOOT_OFFSET_Y) / tile));

  /** Sprite shift while sitting, mirrors the client ([dx, dy] per direction). */
  const SIT_SHIFT = { up: [0, 3], down: [0, 3], left: [0, -8], right: [0, -8] };
  const sitPosition = (chair) => {
    const [dx, dy] = SIT_SHIFT[chair.dir] ?? SIT_SHIFT.down;
    return { x: chair.x + dx, y: chair.y + dy };
  };

  return {
    ...raw,
    isSolidAt,
    sitPosition,
    inBounds: (x, y) => x >= 0 && y >= 0 && x <= raw.width && y <= raw.height,
    randomSpawn() {
      return raw.spawns[Math.floor(Math.random() * raw.spawns.length)];
    },
    chairById: new Map(raw.chairs.map((c) => [c.id, c])),
    portalById: new Map((raw.portals ?? []).map((p) => [p.id, p])),
    computerById: new Map(raw.computers.map((c) => [c.id, c])),
  };
}

/** Every map, keyed by id, plus which one newcomers start in. */
export function loadWorlds(dir = WORLDS_DIR) {
  const index = JSON.parse(readFileSync(resolve(dir, "index.json"), "utf8"));
  const worlds = new Map(index.maps.map((m) => [m.id, loadWorld(resolve(dir, `${m.id}.json`))]));
  return { start: index.start, worlds };
}
